async function api(path, body, options={}) {
  const response=await fetch(path, body===undefined ? undefined : { method:'POST', headers:{'Content-Type':'application/json'}, body:JSON.stringify(body), keepalive:['/api/event','/api/leave','/api/interaction'].includes(path), ...options });
  let data; try { data=await response.json(); } catch { throw new Error('服务暂时没有响应，请稍后重试。'); }
  if(!response.ok) throw Object.assign(new Error(String(data.error || '操作未完成，请重试。').replace(/model_http_401/g,'模型服务鉴权失败（HTTP 401），请检查网站配置的 API Key')),{status:response.status});
  return data;
}
const serveBrowserSources=createBrowserSourceWorker(api,()=>({sessionId:session?.session_id,userId:user?.id,active:!!user&&!!session&&(working||blindPreparing)}));
setInterval(serveBrowserSources,1200);
function interaction(type,extra={}) { return api('/api/interaction',{sessionId:session.session_id,type,eventTime:new Date().toISOString(),...extra}); }
function notice(message, error=false) { clearTimeout(noticeTimer); $('#noticeText').textContent=message; $('#notice').classList.toggle('error',error); $('#notice').hidden=!message; if(message&&!error) noticeTimer=setTimeout(()=>$('#notice').hidden=true,5000); }
$('#closeNotice').addEventListener('click',()=>notice(''));
function screen(id) { for(const name of ['auth','setup','app','boot']) $(`#${name}`).hidden=name!==id; refreshVisibility(); }
function sourceName(id) { return config?.sources?.find(x=>x.id===id)?.name || ({local:'演示内容',wikipedia:'维基百科',hackernews:'Hacker News'})[id] || id; }
function safeURL(raw, image=false) { try { const u=new URL(raw); return (image?u.protocol==='https:':['http:','https:'].includes(u.protocol))&&!u.username&&!u.password?u.href:''; } catch { return ''; } }
function settings() { return { interests:[], sources:[], contentTypes:['text','video'], ...user?.settings }; }
function renderAccount() { const name=user?.displayName||user?.username||''; $('#accountName').textContent=name; $('#avatar').textContent=[...name][0]||''; if(session){$('#exportData').href=`/api/export?sessionId=${encodeURIComponent(session.session_id)}&format=json`;$('#exportDataset').href=`/api/export?sessionId=${encodeURIComponent(session.session_id)}&format=dataset`;} }
async function loadDatasetStatus(retry=false){
 if(!user||!session)return;const owner=user.id,sid=session.session_id;
 try{const data=await api(`/api/dataset/${retry?'retry':'status'}?sessionId=${encodeURIComponent(sid)}`,retry?{}:undefined);if(user?.id!==owner||session?.session_id!==sid)return;
  const place=data.storage==='sqlite+files'?'本机服务器':'云端服务器',pending=data.captures.pending+data.captures.incomplete;
  $('#datasetStatus').textContent=config?.mode==='sample'?'样例浏览交互保存在本机，可下载为数据集。':`${place}自动保存 · ${data.captures.total} 次在线获取，${data.returned_items} 条返回内容。${data.archive_ready?'私有归档已就绪':pending?`${pending} 次归档待重试或未完成`:'私有归档尚未配置'}。参评系统评测会把本组输入发送到云端计算后端并保存运行归档；正式数据包由你选择保留后导出。`;
  $('#datasetRetry').hidden=!data.captures.pending;
 }catch(error){if(user?.id===owner&&session?.session_id===sid)$('#datasetStatus').textContent=`保存状态读取失败：${error.message}`;}
}
$('#datasetRefresh').addEventListener('click',()=>loadDatasetStatus());
$('#datasetRetry').addEventListener('click',async e=>{const button=e.currentTarget;button.disabled=true;try{await loadDatasetStatus(true);}finally{button.disabled=false;}});
function resetAccount() { notice('');modelProfileRequest++;$('#currentModelProfile').value='';profileDirty=false;advancedInterestsAtLoad=[];modelCallsRequest++;modelCallsSignature='';navigation++;feedScrollY=null;researchView.reset();researchDataView.reset();traceView.leave();generation++; queue?.stop(); queue=null; clearTimeout(adaptiveTimer); adaptivePending=false; agentRunning=false; agentIndex=0; outbound=null; observer?.disconnect(); endObserver?.disconnect(); observations.clear(); dwellEvidence.clear(); feedbackById.clear(); savedById.clear(); user=null;session=null;state=null;collection=null;collectionDirty=false;run=null;blindComparison=null;blindBatch=null;blindAuto=false;blindPreparing=false;blindOutbound=null;restoredFeed=[];clearedFeedIds=[];clearingFeed=false;profileInterestsAtLoad=[];working=false;view='feed';prefetchAllowed=true;retryCount=0;$('#loadStatus').hidden=true;$('#retryFeed').hidden=true; $('#feed').innerHTML=''; $('#agentLog').innerHTML=''; }
function newQueue() { queue?.stop(); queue=new RefreshQueue(task=>generateFeed(task.command,task.reason,task.commandId), error=>notice(error.message,true)); }
async function enterAccount(data) {
  await flushExposures(); resetAccount(); user=data.user; const info=data.sessionInfo;
  session=info?.session||null;state=info?.state||null;collection=info?.collection_profile||null;run=info?.lastRun||null;restoredFeed=info?.feed_cards||[];clearedFeedIds=info?.cleared_feed_ids||[];config=info?.config||config;
  for(const [k,v] of Object.entries(info?.feedback_by_content||{})) feedbackById.set(k,v);
  for(const [k,v] of Object.entries(info?.saved_by_content||{})) savedById.set(k,v);
  renderAccount();
  if(!session){ prepareSetup();screen('setup');return; }
  startObservers();newQueue();renderFeed();screen('app');await switchView('feed',false);interaction('enter').catch(error=>notice(error.message,true));
  if(user.type!=='agent'&&!restoredFeed.length&&!clearedFeedIds.length&&!run?.slate?.length) queue.fill();
}
$('#identityForm').addEventListener('submit',async e=>{ e.preventDefault();const button=e.currentTarget.querySelector('button[type=submit]');button.disabled=true;$('#identityError').hidden=true;
  try { await enterAccount(await api('/api/identity',{username:$('#username').value.trim(),type:$('#identityType').value})); }
  catch(error){$('#identityError').textContent=error.message;$('#identityError').hidden=false;} finally{button.disabled=false;}
});
async function logout(){ if(!user)return; navigation++;researchView.leave();researchDataView.leave();queue?.stop();agentRunning=false;generation++;await flushExposures();try{if(session)await api('/api/leave',{sessionId:session.session_id,reason:'logout'});await api('/api/logout',{});resetAccount();screen('auth');}catch(error){notice(error.message,true);} }
$('#switchAccount').addEventListener('click',logout);$('#setupLogout').addEventListener('click',logout);

function interestHTML(selected){ const known=new Set(Object.values(groups).flat());const other=[...new Set([...extras,...selected])].filter(x=>!known.has(x));const all=Object.entries(groups);if(other.length)all.push(['其他',other]);return all.map(([title,items])=>`<div class="interest-group"><strong>${esc(title)}</strong><div>${items.map(item=>`<label class="interest"><input type="checkbox" value="${esc(item)}"${selected.has(item)?' checked':''}>${esc(item)}</label>`).join('')}</div></div>`).join(''); }
function renderInterests(target,selected){ $(`#${target}`).innerHTML=interestHTML(selected); }
function addInterest(input,selected,target){const value=input.value.trim();if(!value)return;if(selected.size>=60&&!selected.has(value)){notice('最多选择 60 个兴趣。',true);return;}extras=[...new Set([...extras,value])];selected.add(value);if(target==='profileInterests')collectionDirty=true;input.value='';renderInterests(target,selected);}
for(const [target,kind] of [['setupInterests','setup'],['profileInterests','profile']]) $(`#${target}`).addEventListener('change',e=>{if(!e.target.matches('input'))return;const set=kind==='setup'?setupInterests:selectedInterests;if(e.target.checked&&set.size>=60){e.target.checked=false;notice('最多选择 60 个兴趣。',true);return;}e.target.checked?set.add(e.target.value):set.delete(e.target.value);});
$('#addInterest').addEventListener('click',()=>addInterest($('#customInterest'),setupInterests,'setupInterests'));
$('#addProfileInterest').addEventListener('click',()=>addInterest($('#newInterest'),selectedInterests,'profileInterests'));
for(const id of ['customInterest','newInterest']) $(`#${id}`).addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();$(`#${id==='customInterest'?'addInterest':'addProfileInterest'}`).click();}});
function prepareSetup(){ $('#recordStorage').textContent=config?.storage==='sqlite+files'?'保存在本机':'保存在云端';const agent=user.type==='agent';setupInterests=new Set(settings().interests);extras=[...(config?.interests||[]),...setupInterests];renderInterests('setupInterests',setupInterests);$('#humanSetup').hidden=false;$('#agentSetup').hidden=!agent;$('#generatedProfile').required=agent;$('#skipSetup').hidden=agent;$('#setupTitle').textContent=agent?'创建一个 Agent':'从喜欢的开始';$('#setupIntro').textContent=agent?'给它一个身份，再开始模拟浏览。':'选一些兴趣，或者写下你的想法。也可以先跳过。';$('#consent').checked=false;$('#setupError').hidden=true;$('#generatedProfile').value='';$('#initialProfile').value=''; }
$('#generateProfile').addEventListener('click',async e=>{const button=e.currentTarget;button.disabled=true;button.textContent='正在生成…';try{const data=await api('/api/generate-profile',{prompt:$('#profileRequest').value});$('#generatedProfile').value=data.profile;button.textContent='重新生成';}catch(error){$('#setupError').textContent=error.message;$('#setupError').hidden=false;button.textContent='重新生成';}finally{button.disabled=false;}});
let skipSetup=false;
$('#skipSetup').addEventListener('click',()=>{if(!$('#setupForm').reportValidity())return;skipSetup=true;$('#setupForm').requestSubmit();});
$('#setupForm').addEventListener('submit',async e=>{e.preventDefault();const button=e.currentTarget.querySelector('button[type=submit]');button.disabled=true;$('#setupError').hidden=true;
  try { const skipping=skipSetup;skipSetup=false;const interestList=skipping?[]:[...setupInterests];const persona={public_profile:skipping?'':$('#initialProfile').value.trim(),hidden_profile:!skipping&&user.type==='agent'?$('#generatedProfile').value.trim():'',subset:'general'};if(user.type==='agent'&&!persona.hidden_profile)throw new Error('请先生成或填写隐藏画像。');const owner=user.id;const updated=await api('/api/settings',{settings:{interests:interestList}});if(user?.id!==owner)return;user=updated.user;const info=await api('/api/session',{consent:$('#consent').checked,recordKind:user.type==='agent'?'synthetic':'human',interests:interestList,collectionProfile:persona});if(user?.id!==owner)return;session=info.session;state=info.state;collection=info.collection_profile;run=info.lastRun;config=info.config||config;renderAccount();startObservers();newQueue();renderFeed();screen('app');await switchView('feed',false);interaction('enter').catch(error=>notice(error.message,true));if(user.type!=='agent')queue.fill(); }
  catch(error){$('#setupError').textContent=error.message;$('#setupError').hidden=false;} finally{button.disabled=false;}
});

async function switchView(next,scroll=true){
  if(!user||!session)return;const token=++navigation,sid=session.session_id,owner=user.id,previous=view,research=['rating','blind'].includes(next);if(previous==='feed'&&scroll)feedScrollY=window.scrollY;
  researchView.leave();researchDataView.leave();
  if(research){prefetchAllowed=false;queue?.cancelRetry();if(queue)queue.prefetch=false;clearTimeout(adaptiveTimer);adaptivePending=false;await commandWrites.catch(()=>{});if(agentRunning){agentRunning=false;$('#agentToggle').disabled=true;$('#agentToggle').textContent='正在暂停…';syncAgentToggle();}queue?.stop();}
  await flushExposures();if(token!==navigation||session?.session_id!==sid||user?.id!==owner)return;if(view==='trace'&&next!=='trace')traceView.leave();view=next;const panel=research?'research':next;for(const name of ['feed','profile','sources','trace','blind','research','data']) $(`#${name}View`).hidden=name!==panel;
  $$('[data-view]').forEach(button=>{const active=button.dataset.view===next;button.classList.toggle('active',active);if(active)button.setAttribute('aria-current','page');else button.removeAttribute('aria-current');});
  if(['blind','rating'].includes(previous)&&!research){blindAuto=false;if(queue?.stopped)newQueue();prefetchAllowed=true;}if(research)researchView.enter(next);if(next==='data')researchDataView.enter();if(next==='profile'){renderProfile();loadDatasetStatus();if(config?.mode!=='sample')loadModelCalls();}if(next==='sources')renderSources();if(next==='trace'){syncAgentToggle();traceView.enter(session.session_id,user.type);}if(next==='feed')window.scrollTo({top:feedScrollY??unreadTop(),behavior:'instant'});else if(scroll)window.scrollTo({top:0,behavior:'instant'});refreshVisibility();if(next==='feed'){if(adaptivePending){adaptivePending=false;queue?.changed();}else maybePrefetch();}
}
$$('[data-view]').forEach(button=>button.addEventListener('click',()=>switchView(button.dataset.view).catch(e=>notice(e.message,true))));
function unreadTop(){const cards=$$('#feed .feed-item[data-seen="false"]');return cards.length?Math.max(0,Math.min(...cards.map(card=>card.getBoundingClientRect().top+window.scrollY))-20):Math.max(0,document.documentElement.scrollHeight-window.innerHeight);}
$('#clearFeed').addEventListener('click',async()=>{
 if(clearingFeed||working||!user||user.type!=='human')return;const owner=user.id,sid=session.session_id;clearingFeed=true;$('#clearFeed').disabled=true;queue?.stop();clearTimeout(adaptiveTimer);adaptivePending=false;
 try{await commandWrites.catch(()=>{});await flushExposures();const removedIds=$$('#feed .feed-item').map(el=>el.dataset.content).slice(-300);await interaction('feed_reset',{removedIds});if(user?.id!==owner||session?.session_id!==sid)return;feedRevision++;clearedFeedIds=[...new Set([...clearedFeedIds,...removedIds])].slice(-300);restoredFeed=[];run=null;for(const el of observations.keys())observer?.unobserve(el);observations.clear();$('#feed').innerHTML='<div class="feed-column"></div><div class="feed-column"></div>';feedScrollY=0;window.scrollTo({top:0,behavior:'instant'});prefetchAllowed=true;retryCount=0;newQueue();if(config?.mode!=='sample')queue.fill();}catch(error){if(user?.id===owner){newQueue();notice(error.message,true);}}finally{clearingFeed=false;$('#clearFeed').disabled=working;}
});
$('#jumpUnread').addEventListener('click',()=>{window.scrollTo({top:unreadTop(),behavior:'instant'});feedScrollY=window.scrollY;maybePrefetch();});
for(const event of ['input','change'])$('#collectionProfileForm').addEventListener(event,()=>{collectionDirty=true;});
$('#collectionProfileForm').addEventListener('submit',async e=>{
 e.preventDefault();const button=e.currentTarget.querySelector('button[type="submit"]');button.disabled=true;const owner=user.id,sid=session.session_id;
 try{const result=await api('/api/collection-profile',{sessionId:sid,version:state.version,expectedProfileId:collection?.profile_id||null,public_profile:$('#publicProfileEditor').value,hidden_profile:user.type==='agent'?$('#hiddenProfileEditor').value:collection?.hidden_profile||'',subset:user.type==='agent'?collection?.subset||'general':'general',interests:[...selectedInterests],expectedInterests:profileInterestsAtLoad});
  if(user?.id!==owner||session?.session_id!==sid)return;collection=result.collection_profile;state=result.state;user=result.user;collectionDirty=false;renderProfile();notice('画像已保存。');scheduleAdaptive();
 }catch(error){notice(error.message,true);}finally{button.disabled=false;}
});
async function loadModelProfile(){
 if(!user||!session)return;const request=++modelProfileRequest,owner=user.id,sid=session.session_id,field=$('#currentModelProfile');
 field.value='正在读取…';
 try{const result=await api(`/api/state?sessionId=${encodeURIComponent(sid)}`);if(request===modelProfileRequest&&user?.id===owner&&session?.session_id===sid&&view==='profile')field.value=JSON.stringify(result.model_profile,null,2);}
 catch(error){if(request===modelProfileRequest&&user?.id===owner&&session?.session_id===sid&&view==='profile')field.value=`画像暂时无法读取：${error.message}`;}
}
async function loadModelCalls(){
  if(!session||!user)return;const serial=++modelCallsRequest,sid=session.session_id,owner=user.id;
  try{
    const {calls}=await api(`/api/model-calls?sessionId=${encodeURIComponent(sid)}`);if(serial!==modelCallsRequest||session?.session_id!==sid||user?.id!==owner||view!=='profile')return;
    const phases=[['unified','决策'],['plan','规划'],['rank','排序'],['simulation','模拟用户']].filter(([key])=>calls[key]);
    $('#modelCallsStatus').textContent=phases.length?'':'还没有模型调用记录。开始生成内容后会在这里显示。';
    const signature=JSON.stringify(calls);if(signature===modelCallsSignature)return;modelCallsSignature=signature;
    const previous=new Map([...document.querySelectorAll('#modelCalls details[data-phase]')].map(el=>[el.dataset.phase,{open:el.open,input:el.querySelector('details')?.open}]));
    $('#modelCalls').innerHTML=phases.map(([key,label])=>{const call=calls[key],old=previous.get(key),when=Number.isFinite(Date.parse(call.at))?new Date(call.at).toLocaleString('zh-CN',{hour12:false}):'时间未知',status=call.status==='failed'?' · 未完成':call.status==='pending'?' · 进行中':'';return `<details class="model-call" data-phase="${key}"${old?.open?' open':''}><summary><strong>${ui.down}<span>最近${label}</span></strong><span>${esc(when+status)}</span></summary><div class="model-call-body"><h3>系统提示词</h3><pre class="model-system" tabindex="0"></pre><details class="model-input"${old?.input?' open':''}><summary>本次实际输入</summary><pre tabindex="0"></pre></details></div></details>`;}).join('');
    for(const [key] of phases){const call=calls[key],root=document.querySelector(`#modelCalls [data-phase="${key}"]`);root.querySelector('.model-system').textContent=call.messages.find(m=>m.role==='system')?.content||'未记录';const content=call.messages.find(m=>m.role==='user')?.content||'未记录';let formatted=content;try{formatted=JSON.stringify(JSON.parse(content),null,2);}catch{}root.querySelector('.model-input pre').textContent=formatted;}
  }catch(error){if(serial===modelCallsRequest&&view==='profile')$('#modelCallsStatus').textContent=`提示词暂时无法读取：${error.message}`;}
}
$('#profileEditor').addEventListener('input',()=>{profileDirty=true;});
$('#profileForm').addEventListener('submit',async e=>{e.preventDefault();const button=e.currentTarget.querySelector('button');button.disabled=true;try{const draft=parseProfile($('#profileEditor').value),owner=user.id,sid=session.session_id;const result=await api('/api/state',{sessionId:sid,version:draft.version,state:draft,expectedInterests:advancedInterestsAtLoad});if(user?.id!==owner||session?.session_id!==sid)return;state=result.state;user=result.user;profileDirty=false;renderProfile();notice('画像已保存。');scheduleAdaptive();}catch(error){notice(error.message,true);}finally{button.disabled=false;}});
function renderProfile(){
 loadModelProfile();
 if(!profileDirty){advancedInterestsAtLoad=[...settings().interests];$('#profileEditor').value=formatProfile(state,advancedInterestsAtLoad);}
 const agent=user?.type==='agent';$('#agentProfileFields').hidden=!agent;$('#hiddenProfileEditor').required=agent;
 if(collectionDirty)return;
 $('#publicProfileEditor').value=state?.profile||'';$('#hiddenProfileEditor').value=agent?collection?.hidden_profile||'':'';
 profileInterestsAtLoad=[...settings().interests];selectedInterests=new Set(profileInterestsAtLoad);extras=[...(config?.interests||[]),...selectedInterests];renderInterests('profileInterests',selectedInterests);
 $('#profileInterestSummary').textContent=selectedInterests.size?`兴趣标签 · 已选 ${selectedInterests.size} 项`:'兴趣标签 · 可选';
}
function renderSources(){const selected=settings().sources;$('#sourceOptions').innerHTML=(config?.sources||[]).map(s=>{const disabled=!s.configured||s.allowed===false;const checked=!disabled&&(!selected.length||selected.includes(s.id));const status=disabled?'未配置':s.status==='failed'?'暂时不可用':s.status==='partial'?'部分可用':'';return `<label class="source-option${disabled?' unavailable':''}"><input type="checkbox" name="source" value="${esc(s.id)}"${checked?' checked':''}${disabled?' disabled':''}>${sourceIcon(s.id)}<span class="source-label">${esc(s.name)}</span><small>${esc(status)}</small></label>`;}).join('');}
$('#sourcesForm').addEventListener('submit',async e=>{e.preventDefault();const button=e.currentTarget.querySelector('button[type=submit]');button.disabled=true;try{const available=$$('#sourceOptions input:not(:disabled)'), sources=available.filter(x=>x.checked).map(x=>x.value);if(!sources.length)throw new Error('请至少保留一个内容来源。');const result=await api('/api/settings',{settings:{sources:sources.length===available.length?[]:sources}});user=result.user;notice('来源已保存。');scheduleAdaptive();}catch(error){notice(error.message,true);}finally{button.disabled=false;}});

function eventBase(el){return {sessionId:el.dataset.session,track:'feed',referenceId:el.dataset.reference,contentId:el.dataset.content,position:Number(el.dataset.position)};}
function endExposure(el,o){if(o.timer){clearTimeout(o.timer);o.timer=null;}if(!o.active)return Promise.resolve();const current=o.active;o.active=null;const duration=Math.min(60000,Math.round(performance.now()-current.start));const promise=current.promise.then(()=>api('/api/event',{...eventBase(el),type:'exposure',exposureId:current.id,phase:'end',visibleMs:duration,...(current.interaction?{visibilityRule:'interaction'}:{}),eventTime:new Date().toISOString()})).then(()=>{if(duration>=3000&&!dwellEvidence.has(el.dataset.content)){dwellEvidence.add(el.dataset.content);if(dwellEvidence.size%3===0)scheduleAdaptive();}}).catch(error=>{if(user)notice(`阅读记录未保存：${error.message}`,true);});pendingWrites.add(promise);promise.finally(()=>pendingWrites.delete(promise));return promise;}
function updateExposure(el,o){const visible=user&&session&&view==='feed'&&!$('#app').hidden&&o.ratio>=.5&&document.visibilityState==='visible'&&document.hasFocus();if(!visible){endExposure(el,o);return;}if(o.active||o.timer)return;const start=performance.now(),eventTime=new Date().toISOString();o.timer=setTimeout(()=>{o.timer=null;if(!user||!session||view!=='feed'||o.ratio<.5||document.visibilityState!=='visible'||!document.hasFocus())return;const active={id:crypto.randomUUID(),start};active.promise=api('/api/event',{...eventBase(el),type:'exposure',exposureId:active.id,phase:'start',visibleMs:0,eventTime});active.promise.catch(error=>{if(user)notice(`阅读记录未保存：${error.message}`,true);});o.active=active;},1000);}
function interactionExposure(el){const o=observations.get(el);if(!o)return null;if(o.active)return o.active;if(o.timer){clearTimeout(o.timer);o.timer=null;}const active={id:crypto.randomUUID(),start:performance.now(),interaction:true};active.promise=api('/api/event',{...eventBase(el),type:'exposure',exposureId:active.id,phase:'start',visibleMs:0,visibilityRule:'interaction',eventTime:new Date().toISOString()});o.active=active;return active;}
function refreshVisibility(){for(const [el,o] of observations)updateExposure(el,o);}
function flushExposures(){return Promise.allSettled([...observations].map(([el,o])=>endExposure(el,o)).concat([...pendingWrites]));}
function startObservers(){observer?.disconnect();endObserver?.disconnect();observations.clear();observer=new IntersectionObserver(entries=>{for(const entry of entries){const o=observations.get(entry.target);if(!o)continue;o.ratio=entry.intersectionRatio;if(entry.isIntersecting&&document.visibilityState==='visible'&&document.hasFocus())entry.target.dataset.seen='true';updateExposure(entry.target,o);}},{threshold:[0,.5,1],rootMargin:window.matchMedia('(max-width:550px)').matches?'0px 0px -145px 0px':'0px 0px -90px 0px'});endObserver=new IntersectionObserver(entries=>{if(entries.some(x=>x.isIntersecting))maybePrefetch();},{rootMargin:'1500px'});endObserver.observe($('#feedEnd'));}
