$('#retryFeed').addEventListener('click',()=>{queue?.cancelRetry();prefetchAllowed=true;$('#retryFeed').hidden=true;if(!$('#feed .feed-column'))$('#feed').innerHTML='<div class="feed-column"></div><div class="feed-column"></div>';queue?.fill();});
$('#commandForm').addEventListener('submit',e=>{e.preventDefault();const value=$('#command').value.trim();if(!value||!queue)return;$('#command').value='';const owner=user.id,sid=session.session_id,eventTime=new Date().toISOString();commandWrites=commandWrites.catch(()=>{}).then(async()=>{const saved=await api('/api/interaction',{sessionId:sid,type:'command',text:value,eventTime});if(user?.id!==owner||session?.session_id!==sid)return;queue.cancelRetry();prefetchAllowed=true;feedRevision++;queue.command(value,saved.id);if(queue.running&&working)notice('已收到，正在调整接下来的内容。');}).catch(error=>{if(!$('#command').value)$('#command').value=value;notice(`指令未保存：${error.message}`,true);});});
async function feedback(el,value,text=''){const owner=user.id,o=observations.get(el);if(o)updateExposure(el,o);const exposure=interactionExposure(el);if(exposure)await exposure.promise;await api('/api/event',{...eventBase(el),type:'feedback',exposureId:exposure?.id||null,value,text,eventTime:new Date().toISOString()});if(user?.id!==owner)return false;feedRevision++;scheduleAdaptive();return true;}
$('#feed').addEventListener('error',e=>{if(e.target instanceof HTMLImageElement){const link=e.target.closest('.media-link');if(link){link.hidden=true;link.closest('.feed-item').classList.add('text-card');}}},true);
$('#feed').addEventListener('click',async e=>{const link=e.target.closest('.feed-item a[href]');if(link){const el=link.closest('.feed-item'),o=observations.get(el);if(o)updateExposure(el,o);const exposure=interactionExposure(el),base=eventBase(el),eventTime=new Date().toISOString();const opened=(exposure?.promise||Promise.resolve()).then(()=>api('/api/event',{...base,type:'open',exposureId:exposure?.id||null,eventTime}));outbound={...base,exposureId:exposure?.id||null,opened,left:false};opened.catch(error=>notice(error.message,true));return;}const button=e.target.closest('[data-action]');if(!button)return;const el=button.closest('.feed-item'),action=button.dataset.action;if(action==='comment'){const form=el.querySelector('.comment-form');form.hidden=!form.hidden;if(!form.hidden)form.querySelector('textarea[aria-label]').focus();return;}button.disabled=true;try{if(action==='save'){const next=!savedById.get(el.dataset.content);if(!await feedback(el,next?'save':'unsave'))return;savedById.set(el.dataset.content,next);button.classList.toggle('selected',next);button.setAttribute('aria-pressed',String(next));}else{if(!await feedback(el,action))return;feedbackById.set(el.dataset.content,action);el.querySelectorAll('[data-action=like],[data-action=dislike]').forEach(b=>{const selected=b===button;b.classList.toggle('selected',selected);b.setAttribute('aria-pressed',String(selected));});}}catch(error){notice(error.message,true);}finally{button.disabled=false;}});
$('#feed').addEventListener('submit',async e=>{const form=e.target.closest('.comment-form');if(!form)return;e.preventDefault();const text=form.querySelector('textarea[aria-label]').value.trim(),button=form.querySelector('button');if(!text)return;button.disabled=true;try{if(await feedback(form.closest('.feed-item'),'comment',text)){form.reset();form.hidden=true;notice('评论已保存。');}}catch(error){notice(error.message,true);}finally{button.disabled=false;}});
function markLeft(){if(outbound)outbound.left=true;if(blindOutbound)blindOutbound.left=true;refreshVisibility();}
function markReturned(){refreshVisibility();if(blindOutbound?.left&&user&&blindOutbound.event.sessionId===session?.session_id&&document.visibilityState==='visible'&&document.hasFocus()){const {opened,event}=blindOutbound;blindOutbound=null;opened.then(()=>api('/api/event',{...event,type:'return',eventTime:new Date().toISOString()})).catch(error=>notice(`盲选返回记录未保存：${error.message}`,true));}if(!outbound||!outbound.left||!user||outbound.sessionId!==session?.session_id||document.visibilityState!=='visible'||!document.hasFocus())return;const {opened,left,...event}=outbound;outbound=null;const eventTime=new Date().toISOString();opened.then(()=>api('/api/event',{...event,type:'return',eventTime})).catch(error=>notice(error.message,true));}
window.addEventListener('scroll',()=>{if(!user||!session||view!=='feed'||user.type==='agent'||Date.now()-lastScrollAt<1500)return;lastScrollAt=Date.now();interaction('scroll',{scrollY:Math.max(0,Math.round(window.scrollY))}).catch(error=>notice(error.message,true));},{passive:true});
