function blindChoiceText(choice,same=false){return ({A:'选择内容 A',B:'选择内容 B',tie:same?'想看共同推荐':'两条都想看',neither:same?'不想看共同推荐':'两条都不想看',insufficient:'无法判断'})[choice] || '已保存';}
function blindDone(choice){
  const comparison=blindComparison;const finished=comparison?.question>=comparison?.total;
  if(comparison?.batch_id)blindBatch={id:comparison.batch_id,total:comparison.total,completed:comparison.question};
  $('#blindRound').hidden=true;$('#blindDoneText').textContent=`${user.type==='agent'&&!(choice==='insufficient'&&comparison?.unavailable)?'Agent ':''}${blindChoiceText(choice,comparison?.same_content)}。`;
  $('#blindDone h2').textContent=finished?'本组盲选已完成':'已记录选择';$('#blindAgain').textContent=finished?'再做一组':'下一题';$('#blindDone').hidden=false;blindComparison=null;
  if(finished)blindAuto=false;updateBlindProgress();
  if(!finished&&(user.type!=='agent'||blindAuto))setTimeout(()=>{if(view==='blind'&&!blindComparison&&(user.type!=='agent'||blindAuto))startBlind();},600);
}
$('#blindStart').addEventListener('click',()=>{blindAuto=user.type==='agent';startBlind();});
$('#blindAgain').addEventListener('click',()=>{blindAuto=user.type==='agent';blindComparison=null;startBlind();});
$('#blindAutoToggle').addEventListener('click',()=>{blindAuto=!blindAuto;updateBlindProgress();if(blindAuto&&!blindPreparing){if(blindComparison)$('#blindSimulate').click();else startBlind();}});
$('#blindChoices').addEventListener('click',async e=>{const button=e.target.closest('[data-blind-choice]');if(!button||!blindComparison)return;const buttons=$$('#blindChoices button'),sid=session.session_id,owner=user.id,cid=blindComparison.id;buttons.forEach(item=>item.disabled=true);try{const result=await api('/api/evaluate',{sessionId:sid,comparisonId:cid,choice:button.dataset.blindChoice,eventTime:new Date().toISOString()});if(result.saved&&session?.session_id===sid&&user?.id===owner&&blindComparison?.id===cid)blindDone(button.dataset.blindChoice);}catch(error){if(session?.session_id===sid)notice(`选择未保存：${error.message}`,true);}finally{buttons.forEach(item=>item.disabled=false);}});
$('#blindAgentSkip').addEventListener('click',async e=>{if(!blindComparison||blindPreparing)return;const button=e.currentTarget,sid=session.session_id,owner=user.id,cid=blindComparison.id;blindPreparing=true;button.disabled=true;try{const result=await api('/api/evaluate',{sessionId:sid,comparisonId:cid,choice:'insufficient',eventTime:new Date().toISOString()});if(result.saved&&session?.session_id===sid&&user?.id===owner&&blindComparison?.id===cid){blindDone('insufficient');$('#blindDoneText').textContent='本题由操作者标记为无法判断。';}}catch(error){if(session?.session_id===sid)notice(`选择未保存：${error.message}`,true);}finally{blindPreparing=false;button.disabled=false;}});
$('#blindSimulate').addEventListener('click',async e=>{if(!blindComparison||blindPreparing)return;blindAuto=true;updateBlindProgress();const button=e.currentTarget,sid=session.session_id,owner=user.id,cid=blindComparison.id;blindPreparing=true;button.disabled=true;button.textContent='Agent 正在选择…';try{const result=await api('/api/blind/simulate',{sessionId:sid,comparisonId:cid});if(session?.session_id===sid&&user?.id===owner&&blindComparison?.id===cid)blindDone(result.choice);}catch(error){blindAuto=false;updateBlindProgress();if(session?.session_id===sid){notice(`模拟选择未完成：${error.message}`,true);button.textContent='重新尝试';}}finally{blindPreparing=false;button.disabled=false;}});
$('#blindCards').addEventListener('click',e=>{const link=e.target.closest('[data-blind-side][href]');if(!link||!blindComparison||!session)return;const side=link.dataset.blindSide,item=blindComparison.cards[side];const event={sessionId:session.session_id,track:'blind',referenceId:blindComparison.id,contentId:item.id,position:1,side};const opened=api('/api/event',{...event,type:'open',eventTime:new Date().toISOString()});blindOutbound={event,opened,left:false};opened.catch(error=>notice(`盲选打开记录未保存：${error.message}`,true));});

function syncAgentToggle(){const source=$('#agentToggle'),button=$('#traceAgentToggle');button.textContent=source.textContent;button.disabled=source.disabled;}
$('#traceAgentToggle').addEventListener('click',()=>$('#agentToggle').click());
$('#agentToggle').addEventListener('click',async e=>{const button=e.currentTarget;if(agentRunning){agentRunning=false;button.disabled=true;button.textContent='正在暂停…';syncAgentToggle();return;}agentRunning=true;button.textContent='暂停';syncAgentToggle();const owner=user.id,sid=session.session_id;const log=text=>{const p=document.createElement('p');p.textContent=text;$('#agentLog').prepend(p);};try{while(agentRunning&&user?.id===owner&&session?.session_id===sid){if(!run||agentIndex>=run.slate.length){const prior=run?.id;await generateFeed('','agent');agentIndex=0;if(!run?.slate.length||run.id===prior)throw new Error('未取得新的内容，已暂停。');}if(!agentRunning)break;const position=agentIndex+1;const result=await api('/api/agent-step',{sessionId:sid,referenceId:run.id,position});if(user?.id!==owner||session?.session_id!==sid)break;agentIndex=position;const names={like:'点赞',dislike:'点踩',save:'收藏',open:'打开'};log(`${result.title}：${result.actions.map(a=>names[a]).join('、')||'略过'}${result.comment?'，评论：'+result.comment:''}`);if(result.command&&agentRunning){const prior=run.id;log(`提出要求：${result.command}`);const saved=await interaction('command',{text:result.command});await generateFeed(result.command,'agent',saved.id);if(run?.id===prior)throw new Error('调整推荐未完成，已暂停。');agentIndex=0;}await new Promise(resolve=>setTimeout(resolve,500));}}catch(error){notice(error.message,true);}finally{agentRunning=false;button.disabled=false;button.textContent='开始浏览';syncAgentToggle();}});
async function boot(){fillIcons();screen('boot');$('#retryBoot').hidden=true;try{config=await api('/api/config');const sample=config.mode==='sample';for(const id of ['sampleModeEntry','sampleDisclosure','sampleModeNote'])$('#'+id).hidden=!sample;$('#modelDisclosure').hidden=sample;$('#modelDiagnostics').hidden=sample;$('#identityType option[value=agent]').disabled=sample;if(sample){$('#identityType').value='human';$('#clearFeed').textContent='清空信息流';$('#retryFeed').textContent='手动重试';}const data=await api('/api/me');if(data.user)await enterAccount(data);else screen('auth');}catch(error){$('#boot p').textContent=`暂时无法连接服务：${error.message}`;$('#retryBoot').hidden=false;}}
$('#retryBoot').addEventListener('click',boot);boot();
